questions.starter:
// saveTheme(theme) — saves to localStorage
// loadTheme() — returns stored theme or 'light' default

// Save 'dark', then load and log

questions.solution:
function saveTheme(theme) {
  localStorage.setItem('theme', theme);
}

function loadTheme() {
  return localStorage.getItem('theme') || 'light';
}

saveTheme('dark');
console.log(loadTheme());

