function addToCart(product) {
  const stored = localStorage.getItem('cart');
  const cart = stored ? JSON.parse(stored) : [];
  cart.push(product);
  localStorage.setItem('cart', JSON.stringify(cart));
  return cart.length;
}

console.log(addToCart({ name: 'Earbuds', price: 4500 }));
console.log(addToCart({ name: 'Phone Case', price: 1200 }));

questions.starter:
// 1. Save prefs object to localStorage
// 2. Load it back
// 3. Update fontSize to 18
// 4. Save updated object
// 5. Load and log fontSize

questions.solution:
const prefs = { theme: 'dark', fontSize: 16, language: 'en' };
localStorage.setItem('prefs', JSON.stringify(prefs));

const loaded = JSON.parse(localStorage.getItem('prefs'));
loaded.fontSize = 18;
localStorage.setItem('prefs', JSON.stringify(loaded));

const final = JSON.parse(localStorage.getItem('prefs'));
console.log(final.fontSize);

function removeFromList(key, id) {
  const stored = localStorage.getItem(key);
  const items = stored ? JSON.parse(stored) : [];
  const filtered = items.filter(item => item.id !== id);
  localStorage.setItem(key, JSON.stringify(filtered));
  return filtered.length;
}

const items = [
  { id: 1, name: 'A' },
  { id: 2, name: 'B' },
  { id: 3, name: 'C' }
];
localStorage.setItem('items', JSON.stringify(items));

console.log(removeFromList('items', 2));
